   236  SomeIpSdEntry::SomeIpSdEntry(const SomeIpSdLayer *pSomeIpSdLayer, size_t offset)
   237          : m_Layer(pSomeIpSdLayer), m_Offset(offset), m_ShadowData(nullptr)
   238  {
   239          EntryType entryType;
   240
   241          someipsdhdrentry *hdr = getSomeIpSdEntryHeader();
   242          TypeInternal internalType = static_cast<TypeInternal>(hdr->type);
   243          auto ttl = getTtl();
   244
   245          switch(internalType)
   246          {
   247          case SomeIpSdEntry::TypeInternal::FindService_Internal:
   248                  entryType = SomeIpSdEntry::EntryType::FindService;
   249                  break;
   250          case SomeIpSdEntry::TypeInternal::OfferService_Internal:
   251                  if (ttl == 0)
   252                  {
   253                          entryType = EntryType::StopOfferService;
   254                  }
   255                  else
   256                  {
   257                          entryType = EntryType::OfferService;
   258                  }
   259                  break;
   260          case SomeIpSdEntry::TypeInternal::SubscribeEventgroup_Internal:
   261                  if (ttl == 0)
   262                  {
   263                          entryType = EntryType::StopSubscribeEventgroup;
   264                  }
   265                  else
   266                  {
   267                          entryType = EntryType::SubscribeEventgroup;
   268                  }
   269                  break;
   270          case SomeIpSdEntry::TypeInternal::SubscribeEventgroupAck_Internal:
   271                  if (ttl == 0)
   272                  {
   273                          entryType = EntryType::SubscribeEventgroupNack;
   274                  }
   275                  else
   276                  {
   277                          entryType = EntryType::SubscribeEventgroupAck;
   278                  }
   279                  break;
   280          default:
   281                  entryType = EntryType::UnknownEntryType;
   282                  break;
   283          }
   284
   285          m_EntryType = entryType;
   286  }
